    max_level = BinaryTreeUtil.max_level(root)
    buffer = []
    BinaryTreeUtil._stringify([ root ], 1, max_level, buffer)
    return ''.join(buffer)

  def _stringify(nodes, level, max_level, buffer):
    if all(node is None for node in nodes):
      return
    height = max_level - level
    edge_lines = 2**(max(height - 1, 0))
    left_spaces = 2**(height) - 1
    between_spaces = 2**(height + 1) - 1
    buffer.append(BinaryTreeUtil.get_whitespaces(left_spaces))

    new_nodes = []
    for node in nodes:
      if node is not None:
        buffer.append(node.val)
        new_nodes.append(node.left)
        new_nodes.append(node.right)
      else:
        buffer.append(' ')
        new_nodes.append(None)
        new_nodes.append(None)
      buffer.append(BinaryTreeUtil.get_whitespaces(between_spaces))

    buffer.append('\n')

    for i in range(1, edge_lines + 1):
      for j in range(0, len(nodes)):
        buffer.append(BinaryTreeUtil.get_whitespaces(left_spaces - i))
        if nodes[j] is None:
          buffer.append(BinaryTreeUtil.get_whitespaces(edge_lines + edge_lines + i + 1))
          continue

        if nodes[j].left is not None:
          buffer.append('/')
        else:
          buffer.append(BinaryTreeUtil.get_whitespaces(1))

        buffer.append(BinaryTreeUtil.get_whitespaces(i + i - 1))


        if nodes[j].right is not None:
          buffer.append('\\')
        else:
          buffer.append(BinaryTreeUtil.get_whitespaces(1))
        buffer.append(BinaryTreeUtil.get_whitespaces(edge_lines + edge_lines - i))
      buffer.append('\n')

    BinaryTreeUtil._stringify(new_nodes, level + 1, max_level, buffer)

  def string_from_levels(levels):
    buffer = []
    max_level = len(levels)
    for l in range(0, len(levels)):
      level = l + 1
      height = max_level - level
      edge_lines = 2**(max(height - 1, 0))
      left_spaces = 2**(height) - 1
      between_spaces = 2**(height + 1) - 1
      buffer.append(BinaryTreeUtil.get_whitespaces(left_spaces))

      nodes = levels[l]

      for node in nodes:
        if node is not None:
          buffer.append(node)
        else:
          buffer.append(' ')
        buffer.append(BinaryTreeUtil.get_whitespaces(between_spaces))
      buffer.append('\n')

      for i in range(1, edge_lines + 1):
        for j in range(0, len(nodes)):
          buffer.append(BinaryTreeUtil.get_whitespaces(left_spaces - i))
          if nodes[j] is None:
            buffer.append(BinaryTreeUtil.get_whitespaces(edge_lines + edge_lines + i + 1))
            continue

          if l == len(levels) - 1 or levels[l + 1][(2*j)] is None:
            buffer.append(BinaryTreeUtil.get_whitespaces(1))
          else:
            buffer.append('/')

          buffer.append(BinaryTreeUtil.get_whitespaces(i + i - 1))

          if l == len(levels) - 1 or levels[l + 1][(2*j) + 1] is None:
            buffer.append(BinaryTreeUtil.get_whitespaces(1))
          else:
            buffer.append('\\')

          buffer.append(BinaryTreeUtil.get_whitespaces(edge_lines + edge_lines - i))
        buffer.append('\n')

    return ''.join(buffer)

  def get_whitespaces(count):
    return ' ' * count

  def max_level(root):
    if root is None:
      return 0
    return 1 + max(BinaryTreeUtil.max_level(root.left), BinaryTreeUtil.max_level(root.right))

