    static std::string join(std::vector<std::string> vec) {
      if (vec.empty()) return "";

      return std::accumulate(
        std::next(vec.begin()), 
        vec.end(), 
        vec[0], 
        [](std::string a, std::string b) {
            return a + b;
        }
      );
    }

    static std::string getWhitespaces (int count) {
      std::vector<std::string> buffer;
      for (int i = 0; i < count; i += 1) buffer.push_back(" ");
      return BinaryTreeUtil::join(buffer);
    }

    static int maxLevel (Node* root) {
      if (root == nullptr) return 0;
      return 1 + std::max(
        BinaryTreeUtil::maxLevel(root->left),
        BinaryTreeUtil::maxLevel(root->right)
      );
    }

    static void _stringify(std::vector<Node*> nodes, int level, int maxLevel, std::vector<std::string> &buffer) {
      if (nodes.size() == 0) return;
      bool allNull = true;
      for (Node* node : nodes) {
        if (node != nullptr) allNull = false;
      }
      if (allNull) return;

      int height = maxLevel - level;
      int edgeLines = pow(2, (std::max(height - 1, 0)));
      int leftSpaces = pow(2, (height)) - 1;
      int betweenSpaces = pow(2, (height + 1)) - 1;
      buffer.push_back(BinaryTreeUtil::getWhitespaces(leftSpaces));

      std::vector<Node*> newNodes;
      for (Node* node : nodes) {
        if (node != nullptr) {
          buffer.push_back(node->val);
          newNodes.push_back(node->left);
          newNodes.push_back(node->right);
        } else {
          buffer.push_back(" ");
          newNodes.push_back(nullptr);
          newNodes.push_back(nullptr);
        }
        buffer.push_back(BinaryTreeUtil::getWhitespaces(betweenSpaces));
      }

      buffer.push_back("\n");

      for (int i = 1; i <= edgeLines; i += 1) {
        for (int j = 0; j < nodes.size(); j += 1) {
            buffer.push_back(BinaryTreeUtil::getWhitespaces(leftSpaces - i));
            if (nodes[j] == nullptr) {
                buffer.push_back(BinaryTreeUtil::getWhitespaces(edgeLines + edgeLines + i + 1));
                continue;
            }

            if (nodes[j]->left != nullptr) {
              buffer.push_back("/");
            } else {
              buffer.push_back(BinaryTreeUtil::getWhitespaces(1));
            }

            buffer.push_back(BinaryTreeUtil::getWhitespaces(i + i - 1));

            if (nodes[j]->right != nullptr) {
              buffer.push_back("\\");
            } else {
              buffer.push_back(BinaryTreeUtil::getWhitespaces(1));
            }

            buffer.push_back(BinaryTreeUtil::getWhitespaces(edgeLines + edgeLines - i));
        }

        buffer.push_back("\n");
      }

      BinaryTreeUtil::_stringify(newNodes, level + 1, maxLevel, buffer);
    }

    static std::string stringify(Node* root) {
      int maxLevel = BinaryTreeUtil::maxLevel(root);
      std::vector<std::string> buffer;
      std::vector<Node*> nodes { root };
      BinaryTreeUtil::_stringify(nodes, 1, maxLevel, buffer);
      return BinaryTreeUtil::join(buffer);
    }

    static std::string stringFromLevels(std::vector< std::vector<std::string> > levels) {
      std::vector<std::string> buffer;
      int maxLevel = levels.size();
      for (int l = 0; l < levels.size(); l += 1) {
        int level = l + 1;
        int height = maxLevel - level;
        int edgeLines = pow(2, (std::max(height - 1, 0)));
        int leftSpaces = pow(2, (height)) - 1;
        int betweenSpaces = pow(2, (height + 1)) - 1;
        buffer.push_back(BinaryTreeUtil::getWhitespaces(leftSpaces));

        std::vector<std::string> nodes = levels[l];

        for (std::string node : nodes) {
          if (node != "NULL") {
            buffer.push_back(node);
          } else {
            buffer.push_back(" ");
          }
          buffer.push_back(BinaryTreeUtil::getWhitespaces(betweenSpaces));
        }
        buffer.push_back(("\n"));

        for (int i = 1; i <= edgeLines; i += 1) {
          for (int j = 0; j < nodes.size(); j += 1) {
              buffer.push_back(BinaryTreeUtil::getWhitespaces(leftSpaces - i));
              if (nodes[j] == "NULL") {
                  buffer.push_back(BinaryTreeUtil::getWhitespaces(edgeLines + edgeLines + i + 1));
                  continue;
              }

              if (l == levels.size() - 1 || levels[l + 1][(2*j)] == "NULL") {
                buffer.push_back(BinaryTreeUtil::getWhitespaces(1));
              } else {
                buffer.push_back("/");
              }

              buffer.push_back(BinaryTreeUtil::getWhitespaces(i + i - 1));

              if (l == levels.size() - 1 || levels[l + 1][(2*j) + 1] == "NULL") {
                buffer.push_back(BinaryTreeUtil::getWhitespaces(1));
              } else {
                buffer.push_back("\\");
              }

              buffer.push_back(BinaryTreeUtil::getWhitespaces(edgeLines + edgeLines - i));
          }

          buffer.push_back(("\n"));
        }
      }

      return BinaryTreeUtil::join(buffer);
    }
};

