Node* buildTreeInPost(std::vector<std::string> inorder, std::vector<std::string> postorder) {
  if (inorder.size() == 0) {
    return nullptr;
  }

  std::string val = postorder[postorder.size() - 1];
  Node* root = new Node(val);

  auto p = std::find(inorder.begin(), inorder.end(), val);
  std::vector<std::string> leftIn(inorder.begin(), p);
  std::vector<std::string> rightIn(p + 1, inorder.end());
  std::vector<std::string> leftPost(postorder.begin(), postorder.begin() + leftIn.size());
  std::vector<std::string> rightPost(postorder.begin() + leftIn.size(), postorder.end() - 1);

  root->left = buildTreeInPost(leftIn, leftPost);
  root->right = buildTreeInPost(rightIn, rightPost);

  return root;
}
